public class FindMax {
    public static void main(String[] args) {
        int[] temps = {-4, -9, -2};
        int max = temps[0];

        for (int t : temps) {
            if (t > max) {
                max = t;
            }
        }

        System.out.println(max);
    }
}

public class FindMin {
    public static void main(String[] args) {
        int[] scores = {6, 2, 8};
        int min = scores[0];

        for (int score : scores) {
            if (score < min) {
                min = score;
            }
        }

        System.out.println(min);
    }
}

